// Terminal — SDK (build tooling + dev runtime)
// $ dotnet --list-sdks
// 8.0.404 [/usr/share/dotnet/sdk]

// Terminal — runtimes only (what executes published apps)
// $ dotnet --list-runtimes
// Microsoft.AspNetCore.App 8.0.11 [/usr/share/dotnet/shared/Microsoft.AspNetCore.App]
// Microsoft.NETCore.App 8.0.11 [/usr/share/dotnet/shared/Microsoft.NETCore.App]

// A machine with runtime but no SDK cannot `dotnet build`

// Terminal
// dotnet publish -c Release -r linux-x64 --self-contained true

// csproj alternative:
<PropertyGroup>
  <RuntimeIdentifier>linux-x64</RuntimeIdentifier>
  <SelfContained>true</SelfContained>
  <PublishSingleFile>true</PublishSingleFile>
</PropertyGroup>

// Output bundles the runtime — larger artifact, no shared runtime on host.
// Useful for immutable AMIs running SQS consumers without dotnet on the box.

// Web API Program.cs
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddHostedService<SqsOrderWorker>();
var app = builder.Build();
app.MapGet("/health", () => Results.Ok("up"));
app.Run();

// SqsOrderWorker uses the same DI container and CancellationToken
// as HTTP endpoints — one process, one runtime, shared configuration.
